            keyLock.lockInterruptibly(10, TimeUnit.SECONDS);
            try {
                cache.put(key, RandomString.make(2*1024*1024), 5, TimeUnit.SECONDS);
            } finally {
                if (keyLock != null) {
                    keyLock.unlock();
                }
            }
        }
        
        System.out.println("done");
    }
